<div class="dashboard-heading"><div><h1>داشبورد مدیریت</h1><p class="muted">نمای کلی عملکرد سامانهٔ مرشد</p></div><?php if($canOperate): ?><a class="secondary" href="<?= $this->h($this->url('/reports')) ?>">گزارش‌های سامانه <?= $this->icon('arrow') ?></a><?php endif; ?></div>
<div class="dashboard-stats section"><?php foreach(['users'=>['کاربران ثبت‌شده','users'],'mentors'=>['مرشدهأ فعال','user'],'experiences'=>['تجربه‌های منتشرشده','book'],'bookings'=>['درخواست‌های گفت‌وگو','calendar']] as $key=>[$label,$icon]): ?><article class="dashboard-stat"><span class="service-icon"><?= $this->icon($icon) ?></span><p><?= $this->h($label) ?></p><strong><?= $this->h(number_format($stats[$key])) ?></strong><small>براساس داده‌های ثبت‌شده</small></article><?php endforeach; ?></div>
<?php if($canOperate): ?><div class="dashboard-grid section"><section class="card"><h2>روند درخواست‌های گفت‌وگو</h2><p class="muted small">تعداد درخواست‌های ثبت‌شده در ۷ روز اخیر (UTC)</p><?php $max=max(1,...array_column($trend,'count'));$points=[];foreach($trend as $i=>$day){$points[]=(20+$i*100).','.round(150-$day['count']/$max*120,2);} ?><svg class="dashboard-chart" viewBox="0 0 640 190" role="img" aria-label="نمودار درخواست‌های هفت روز اخیر"><path d="M20 30H620M20 90H620M20 150H620" class="chart-grid"/><polyline points="<?= $this->h(implode(' ',$points)) ?>" class="chart-line"/><?php foreach($trend as $i=>$day): ?><circle cx="<?= 20+$i*100 ?>" cy="<?= round(150-$day['count']/$max*120,2) ?>" r="4" class="chart-dot"/><text x="<?= 20+$i*100 ?>" y="182" text-anchor="middle"><?= $this->h($day['label']) ?></text><?php endforeach; ?></svg><details><summary>مشاهدهٔ اعداد نمودار</summary><?php foreach($trend as $day): ?><p class="small"><bdi><?= $this->h($day['label']) ?></bdi>: <?= $day['count'] ?> درخواست</p><?php endforeach; ?></details></section>
<section class="card"><h2>وضعیت درخواست‌ها</h2><?php if(!$bookingStates): ?><p class="empty muted">هنوز درخواستی ثبت نشده است.</p><?php else: foreach($bookingStates as $row): ?><div class="dashboard-state"><span><?= $this->status($row['state']) ?></span><b><?= (int)$row['total'] ?></b></div><?php endforeach; endif; ?><p class="small muted">ثبت درخواست عمومی و تأیید مرشد فعال است؛ تماس و چت داخل سامانه هنوز آماده نیست.</p></section></div>
<section class="card section"><div class="section-head"><h2>آخرین درخواست‌های گفت‌وگو</h2><a class="textlink" href="<?= $this->h($this->url('/bookings')) ?>">مشاهدهٔ همه</a></div><?php if(!$recentBookings): ?><p class="empty muted">پس از ثبت اولین درخواست، اطلاعات این بخش نمایش داده می‌شود.</p><?php else: ?><div class="table-scroll"><table><thead><tr><th>درخواست‌کننده</th><th>مرشد</th><th>وضعیت</th></tr></thead><tbody><?php foreach($recentBookings as $row): ?><tr><td><?= $this->h($row['user_name']) ?></td><td><?= $this->h($row['mentor_name']) ?></td><td><span class="tag"><?= $this->status($row['state']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php else: ?><section class="card section"><h2>مدیریت محتوا</h2><p class="muted">تجربه‌های ارسال‌شده و موضوعات را از منوی مدیریت بررسی کنید.</p><a class="primary" href="<?= $this->h($this->url('/experiences')) ?>">بررسی تجربه‌ها</a></section><?php endif; ?>
<?php if($canOperate): ?><section class="card section"><h2>پیگیری پشتیبانی</h2><p><?= $this->number($stats['support_open']) ?> درخواست باز در انتظار رسیدگی است.</p><a class="primary" href="<?= $this->h($this->url('/support')) ?>">مشاهده و پاسخ به کاربران</a></section><?php endif; ?>
